<script setup>
import { computed, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useSystemStore } from '../stores/system'
import { pushReturnTarget } from '../lib/navigation-return'
import { PARCEL_SHIPMENTS } from '../lib/parcel-shell-data'
import { useParcelShellState } from '../composables/useParcelShellState'
const router=useRouter();const route=useRoute();const systemStore=useSystemStore();const shell=useParcelShellState();const query=ref('');const selected=ref(null)
const isZh=computed(()=>String(systemStore.settings.system.language||'zh-CN').toLowerCase().startsWith('zh'));const night=computed(()=>systemStore.settings.appearance.colorMode==='night'||systemStore.currentTheme==='zen');const tx=(zh,en)=>isZh.value?zh:en;const lx=(o,k)=>o?.[`${k}${isZh.value?'Zh':'En'}`]||''
const results=computed(()=>{const q=query.value.trim().toLowerCase();return q?PARCEL_SHIPMENTS.filter(x=>[x.code,x.titleZh,x.titleEn,x.senderZh,x.senderEn].some(v=>String(v).toLowerCase().includes(q))):PARCEL_SHIPMENTS})
</script>
<template>
<main class="posta" :class="{night}" data-testid="parcel-app"><header><button type="button" :aria-label="tx('返回','Back')" data-testid="parcel-back" @click="pushReturnTarget(router,route,'/home')"><i class="fas fa-chevron-left"/></button><div class="logo"><i class="fas fa-box"/></div><div><b>{{tx('递送','POSTA')}}</b><small>{{tx('包裹与寄件服务','Parcel & sending service')}}</small></div><span>{{shell.pinnedShipmentIds.value.length}}</span></header>
<section v-if="shell.activeTab.value==='track'" class="page" data-testid="parcel-track"><div class="hero"><div><small>{{tx('包裹板','PARCEL BOARD')}}</small><h1>{{tx('每一件东西，\n都有来路。','Every parcel\nhas a trail.')}}</h1></div><i class="fas fa-arrow-down-long"/></div><label class="search"><i class="fas fa-magnifying-glass"/><input v-model="query" data-testid="parcel-search" :placeholder="tx('运单号、物品或寄件方','Tracking code, item, or sender')"/></label><div class="shipments"><button v-for="item in results" :key="item.id" type="button" :data-testid="`parcel-shipment-${item.id}`" @click="selected=item"><div class="status" :class="item.status"><i :class="item.status==='delivered'?'fas fa-check':item.status==='pickup_ready'?'fas fa-locker':'fas fa-truck-fast'"/><span>{{lx(item,'status')}}</span></div><div><small>{{item.code}} · {{lx(item,'sender')}}</small><h2>{{lx(item,'title')}}</h2><p>{{lx(item,'last')}}</p></div><strong>{{lx(item,'eta')}}</strong></button></div></section>
<section v-else-if="shell.activeTab.value==='send'" class="page" data-testid="parcel-send"><div class="title"><small>{{tx('寄件草稿','SEND DRAFT')}}</small><h1>{{tx('先把寄件信息准备好','Prepare the send details')}}</h1><p>{{tx('只保存本机草稿，不创建运单、不计费、不预约取件。','This saves only a local draft; it creates no label, quote, or pickup booking.')}}</p></div><div class="send-form"><label><span>{{tx('收件人','Recipient')}}</span><input :value="shell.sendDraft.value.recipient" @input="shell.updateSendDraft({recipient:$event.target.value})"/></label><label><span>{{tx('地址标签','Address label')}}</span><input :value="shell.sendDraft.value.addressLabel" :placeholder="tx('例如：工作室 / 家','e.g. Studio / Home')" @input="shell.updateSendDraft({addressLabel:$event.target.value})"/></label><div class="type-row"><button type="button" :class="{active:shell.sendDraft.value.itemType==='parcel'}" @click="shell.updateSendDraft({itemType:'parcel'})"><i class="fas fa-box"/>{{tx('包裹','Parcel')}}</button><button type="button" :class="{active:shell.sendDraft.value.itemType==='document'}" @click="shell.updateSendDraft({itemType:'document'})"><i class="fas fa-envelope"/>{{tx('文件','Document')}}</button></div><label><span>{{tx('备注','Note')}}</span><textarea :value="shell.sendDraft.value.note" @input="shell.updateSendDraft({note:$event.target.value})"/></label><footer><b>LOCAL DRAFT</b><span>{{tx('尚未生成运单','No shipping label created')}}</span></footer></div></section>
<section v-else-if="shell.activeTab.value==='inbox'" class="page" data-testid="parcel-inbox"><div class="title"><small>{{tx('递送消息','DELIVERY INBOX')}}</small><h1>{{tx('只看与包裹有关的消息','Only parcel-related updates')}}</h1></div><div class="inbox"><article><i class="fas fa-box-open"/><div><b>{{tx('自提件已入柜','Pickup parcel is ready')}}</b><p>{{tx('录音棚线材包已到圣水自提柜。','The studio cable kit is at the Seongsu locker.')}}</p></div><span>16:20</span></article><article><i class="fas fa-triangle-exclamation"/><div><b>{{tx('一条来源已失效','One source has expired')}}</b><p>{{tx('海外样品包需要未来物流 owner 刷新。','The overseas sample needs a future logistics owner refresh.')}}</p></div><span>09:05</span></article></div></section>
<section v-else class="page" data-testid="parcel-me"><div class="title"><small>{{tx('我的递送','MY POSTA')}}</small><h1>{{tx('常用选择','Everyday preferences')}}</h1></div><article class="toggle"><div><b>{{tx('自提提醒偏好','Pickup reminder preference')}}</b><p>{{tx('首版只记录偏好，不发送系统通知。','S1 records only a preference and sends no system notification.')}}</p></div><button type="button" role="switch" :aria-checked="shell.pickupReminderEnabled.value" @click="shell.togglePickupReminder"><span/></button></article></section>
<nav><button v-for="tab in [{id:'track',zh:'查件',en:'Track',icon:'fas fa-location-crosshairs'},{id:'send',zh:'寄件',en:'Send',icon:'fas fa-paper-plane'},{id:'inbox',zh:'消息',en:'Inbox',icon:'fas fa-inbox'},{id:'me',zh:'我的',en:'Me',icon:'fas fa-user'}]" :key="tab.id" type="button" :class="{active:shell.activeTab.value===tab.id}" :data-testid="`parcel-tab-${tab.id}`" @click="shell.setActiveTab(tab.id)"><i :class="tab.icon"/><span>{{tx(tab.zh,tab.en)}}</span></button></nav>
<aside v-if="selected" data-testid="parcel-detail"><button type="button" :aria-label="tx('关闭','Close')" @click="selected=null"><i class="fas fa-xmark"/></button><small>{{selected.code}}</small><h1>{{lx(selected,'title')}}</h1><div class="route-line"><i/><i/><i/></div><h2>{{lx(selected,'status')}}</h2><p>{{lx(selected,'last')}}</p><b>{{lx(selected,'eta')}}</b><div v-if="selected.mapPlaceId" class="map-ref"><i class="fas fa-map-location-dot"/><span>{{tx('引用现有 Map 地点','References existing Map place')}}</span><small>{{selected.mapPlaceId}} · READ ONLY</small></div><button class="pin" type="button" :aria-pressed="shell.pinnedShipmentIds.value.includes(selected.id)" @click="shell.togglePinned(selected.id)"><i class="fas fa-thumbtack"/>{{shell.pinnedShipmentIds.value.includes(selected.id)?tx('取消置顶','Unpin'):tx('置顶包裹','Pin parcel')}}</button><p class="boundary">{{tx('固定物流记录仅供壳子预览；不会创建签收、改地址、退款、Map 路线或事件完成结果。','Authored tracking records are preview-only; they create no delivery proof, address change, refund, Map route, or event result.')}}</p></aside>
</main>
</template>
<style scoped>
