.status{height:100%;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:8px;color:#fff;background:var(--blue)}.status.delivered{background:#4e795b}.status.source_stale{background:#736b78}.status i{font-size:24px}.status span{font-size:9px;font-weight:900}.shipments>button>div:nth-child(2){padding:16px}.shipments small,.shipments p{color:var(--muted)}.shipments h2{margin:7px 0}.shipments strong{padding:16px;font-size:10px}.title{max-width:680px;margin:18px 0 25px}.title h1{margin:8px 0;font:900 40px/1 Georgia,"Noto Serif CJK SC",serif}.title p{color:var(--muted);line-height:1.6}.send-form{max-width:720px;padding:24px;display:grid;gap:17px;border:1px solid var(--line);background:var(--paper)}.send-form label span{display:block;margin-bottom:7px;font-size:10px;font-weight:900}.send-form input,.send-form textarea{width:100%;box-sizing:border-box;border:1px solid var(--line);color:inherit;background:var(--bg)}.send-form input{height:44px;padding:0 11px}.send-form textarea{min-height:90px;padding:11px}.type-row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.type-row button{min-height:54px;border:1px solid var(--line);color:inherit;background:transparent}.type-row button.active{color:#fff;background:var(--blue)}.type-row i{margin-right:7px}.send-form footer{display:flex;justify-content:space-between;color:var(--muted)}.send-form footer b{color:var(--orange)}.inbox{display:grid;gap:9px}.inbox article{padding:20px;display:grid;grid-template-columns:42px 1fr auto;gap:13px;border:1px solid var(--line);background:var(--paper)}.inbox article>i{color:var(--orange);font-size:22px}.inbox p{color:var(--muted)}.toggle{padding:24px;display:flex;justify-content:space-between;border:1px solid var(--line);background:var(--paper)}.toggle p{color:var(--muted)}.toggle>button{width:56px;height:34px;padding:4px;border:0;border-radius:999px;background:#879497}.toggle>button[aria-checked=true]{background:var(--orange)}.toggle>button span{display:block;width:26px;height:26px;border-radius:50%;background:#fff;transition:.2s}.toggle>button[aria-checked=true] span{transform:translateX(22px)}nav{position:absolute;left:50%;bottom:calc(10px + env(safe-area-inset-bottom));transform:translateX(-50%);width:min(520px,calc(100% - 24px));height:62px;padding:5px;display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);border-radius:8px 20px 8px 8px;background:color-mix(in srgb,var(--paper) 92%,transparent);backdrop-filter:blur(16px)}nav button{border:0;border-radius:5px;color:var(--muted);background:transparent}nav button.active{color:#fff;background:var(--blue)}nav i,nav span{display:block}nav span{margin-top:4px;font-size:9px}aside{position:absolute;z-index:20;inset:0 0 0 auto;width:min(560px,100%);padding:calc(110px + env(safe-area-inset-top)) 38px 55px;box-sizing:border-box;overflow-y:auto;color:var(--ink);background:var(--paper);box-shadow:-25px 0 70px #0005}aside>button{position:absolute;right:18px;top:calc(28px + env(safe-area-inset-top))}aside>small{letter-spacing:.12em}aside h1{font:900 42px/1 Georgia,"Noto Serif CJK SC",serif}aside h2{margin-top:25px}.route-line{height:35px;display:flex;align-items:center;gap:0}.route-line i{width:13px;height:13px;border-radius:50%;background:var(--orange)}.route-line i:nth-child(2){height:2px;flex:1;border-radius:0;background:var(--line)}.map-ref{margin:25px 0;padding:14px;display:grid;grid-template-columns:28px 1fr;gap:4px 10px;border:1px solid var(--line)}.map-ref>i{grid-row:1/3;color:var(--blue)}.map-ref small{color:var(--muted);overflow-wrap:anywhere}.pin{width:100%;min-height:46px;border:0;color:#fff;background:var(--orange);font-weight:900}.pin i{margin-right:8px}.boundary{padding:13px;color:var(--muted);background:var(--bg);line-height:1.55}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #ffb08f;outline-offset:2px}@media(max-width:700px){.posta>header{height:82px;padding:calc(28px + env(safe-area-inset-top)) 10px 8px}.page{height:calc(100% - 82px);padding:14px 12px 100px}.hero{min-height:260px;padding:27px}.hero h1{font-size:39px}.shipments>button{grid-template-columns:72px minmax(0,1fr)}.shipments strong{grid-column:2;padding-top:0}.status span{writing-mode:vertical-rl}.send-form{padding:17px}.inbox article{grid-template-columns:34px 1fr}.inbox article>span{grid-column:2}.toggle{gap:15px}aside{padding:100px 20px 55px}aside h1{font-size:36px}}
